insert into public.catalogo_maestro_platos (plato_id, sinonimos, resumen, hack, que_observar, activo)
values
('milanesa-carne', ARRAY['milanesa de carne', 'milanesa', 'milanesa vacuna', 'milanesa sola']::text[], 'Clásico innegable. La carne aporta proteína noble y el rebozado suma carbohidratos rápidos. Si se hace al horno con aceite medido, logras un balance excelente sin sacrificar sabor.', 'Mantené el corte que te guste pero controlá el espesor del rebozado: a menor capa de pan, menor absorción de grasa en cocción. Tip extra: sumale una pizca de pimentón dulce u orégano al pan rallado; no solo realza el sabor, sino que ayuda a mitigar la pesadez estomacal.', ' Compara saciedad y pesadez digestiva frente a la versión frita tradicional. Nota la diferencia en tu energía a las 2 horas de comer.', true),
('milanesa-pollo', ARRAY['milanesa de pollo', 'suprema', 'suprema de pollo']::text[], 'Una excelente opción de proteína magra. El pollo es liviano, pero el rebozado y la técnica de cocción definen el impacto final en tu digestión.', 'Prioriza la cocción al horno o plancha con rocío vegetal. Si la hacés frita, asegurate de que el aceite esté a temperatura alta para que no chupe grasa de más. Tip extra: un toque de provenzal (ajo y perejil deshidratado) en el rebozado potencia la digestión y le da un golpe de sabor bárbaro.', ' Evalúa cómo se siente tu estómago en comparación con carnes rojas pesadas; busca notar liviandad sin perder saciedad.', true),
('milanesa-higado', ARRAY['milanesa de higado', 'higado a la milanesa']::text[], '¡Excelente elección! Estás metiendo una auténtica "multivitamínica natural": el hígado es una fuente brutal de hierro bio-disponible, vitamina A y complejo B. Un plato con una densidad nutricional altísima.', 'Para contrarrestar el sabor metálico característico y potenciar la absorción del hierro, rociála con abundante jugo de limón fresco apenas sale del fuego. Tip extra: sumale una pizca de comino en la cocción, ayuda a que caiga mucho más liviano y evita gases.', ' Presta atención a tu nivel de energía y fatiga en las horas posteriores; este alimento suele dar un envión anímico y físico notable por su perfil de nutrientes.', true),
('milanesa-berenjena', ARRAY['milanesa de berenjena', 'berenjena a la milanesa']::text[], 'Una alternativa vegetal fantástica y liviana. La berenjena aporta volumen, fibra y baja densidad calórica, ideal para sumar saciedad sin sobrecargar el sistema digestivo.', 'La berenjena actúa como una esponja de aceite. Antes de rebozar, salala unos minutos para que suelte el agua amarga y sécala bien; eso evita que absorba grasa de más en la cocción. Tip extra: un toque de pimienta negra recién molida activa las papilas y mejora la termogénesis.', ' Nota la ligereza post-comida; es un plato que otorga gran volumen gástrico con una digestión sumamente rápida y limpia.', true),
('milanesa-napolitana', ARRAY['milanesa a la napolitana', 'napolitana', 'milanesa napolitana']::text[], 'El plato supremo de los bodegones. Combina la proteína de la carne o pollo con el aporte fresco de la salsa de tomate y el toque graso del queso.', 'Si la hacés en casa, prioriza una base de salsa de tomate natural y una capa moderada de muzarella. Tip extra: sumale hojas de albahaca fresca arriba post-cocción; los aceites esenciales de la albahaca mejoran notablemente la digestión de las grasas lácteas del queso.', ' Compara el nivel de pesadez o letargo comparado con una milanesa sola; el queso fundido más la salsa cambian el tiempo de vaciado gástrico.', true),
('milanesa-caballo', ARRAY['milanesa a caballo', 'milanesa con huevo frito']::text[], 'Combinación de alto voltaje proteico y lipídico. La proteína de la carne se duplica con la alta calidad nutricional de la yema de huevo. Un plato que rinde culto a la saciedad.', 'Hacé el huevo a la plancha con mínimo aceite o agua (técnica poché/plancha) para sumar la yema cremosa sin saturar el plato con grasa extra de fritura. Tip extra: un toque de pimienta negra o pimentón sobre la yema estimula las secreciones gástricas.', ' Registra tu nivel de saciedad: este combo elimina por completo los picos de hambre voraz a la tarde gracias a su densidad de grasas limpias y proteínas.', true),
('bife-vacuno', ARRAY['bife de carne', 'bife de chorizo', 'bife vacuno', 'bife de lomo', 'bife']::text[], '¡Excelente elección! Estás yendo a la fuente primaria: proteína de altísima calidad biológica, cero ultraprocesados, rica en zinc y creatina natural. Un pilar fundamental para mantener la masa muscular y la estabilidad metabólica.', 'Controla el punto de cocción: no quemes ni carbonices la carne en exceso (la costra muy negra genera compuestos pro-inflamatorios). Tip extra: marinalo antes con un toque de ajo aplastado y romero fresco; además de perfumar, los antioxidantes de las hierbas protegen la carne durante el grillado.', ' Observa la claridad mental y la estabilidad de energía que te deja este plato: al no tener harinas ni azúcares ocultos, el bostezo post-almuerzo desaparece.', true),
('bife-pollo', ARRAY['bife de pollo', 'pechuga a la plancha', 'pollo a la plancha']::text[], 'Proteína magra por excelencia. Limpio, versátil y de rápida asimilación por el organismo. Una base perfecta para cualquier estrategia nutricional diaria.', 'El gran pecado del bife de pollo es pasarlo de cocción y dejarlo seco como una suela. Cocinalo a fuego vivo el tiempo justo para conservar jugosidad. Tip extra: un chorrito de jugo de limón y pimentón ahumado alimonado levantan el perfil de sabor sin sumar una sola caloría extra.', ' Nota cómo responde tu digestión: al ser una carne blanca magra, el tránsito estomacal es ágil y libre de pesadez.', true),
('bife-cerdo', ARRAY['bife de cerdo', 'carre de cerdo', 'cerdo a la plancha']::text[], 'Un corte sumamente noble, injustamente rotulado en el pasado. Hoy los cortes magros de cerdo (como el carré o jamón) tienen un perfil graso muy saludable y aportan altísima cantidad de vitamina B1.', 'Cocinalo a punto (ligeramente rosado en el centro si la carne es de confianza) para mantener toda su terneza y evitar que se seque. Tip extra: acompañalo con una pizca de mostaza natural en grano; la mostaza estimula las enzimas digestivas para procesar mejor las grasas del cerdo.', ' Evalúa la saciedad prolongada que te otorga frente al pollo; el cerdo tiene una densidad de nutrientes y perfil lipídico muy interesante.', true),
('bife-merluza', ARRAY['bife de merluza', 'merluza a la plancha', 'filet de merluza', 'pescado a la plancha']::text[], 'Excelente opción de pescado blanco. Aporta proteínas de fácil digestión y ácidos grasos livianos, ideal para almorzar o cenar sin generar somnolencia.', 'Al ser un pescado muy delicado, évita cocinarlo de más para que no se desarme. Si va a la plancha, asegurate de que esté bien caliente y con unas gotas de aceite para que no se pegue. Tip extra: impregnarlo con jugo de limón y una pizca de jengibre rallado le da un giro bio-hack de sabor y activa la digestión gástrica de forma magistral.', ' Registra la liviandad absoluta con la que te levantás de la mesa; la merluza se digiere a una velocidad notable sin restar energía.', true),
('hamburguesa-carne', ARRAY['hamburguesa de carne', 'hamburguesa vacuna', 'hamburguesa casera']::text[], 'Si es carne picada real (preferentemente seleccionada), es un plato denso en nutrientes, proteínas y grasas saludables. El formato práctico de la carne vacuna.', 'Evitá el exceso de pan industrial ultraprocesado. Si la comís al plato o con un pan de buena calidad, el impacto metabólico cambia por completo. Tip extra: sumale cebolla rehogada lentamente en la base; los compuestos sulfurados de la cebolla ayudan a la función hepática y suavizan la digestión de la carne roja.', ' Compara tu nivel de saciedad frente a comer la carne en bife; el formato picado a veces acelera la masticación, así que presta atención a comer más lento.', true),
('hamburguesa-pollo', ARRAY['hamburguesa de pollo']::text[], 'Una variante proteica más liviana que la de carne vacuna, ideal para sumar volumen diario de proteínas sin la carga calórica de las carnes rojas grasas.', 'Cuidado con las versiones industriales congeladas que traen féculas y aditivos ocultos; prioriza las caseras o picadas de pollo real. Tip extra: un toque de curry suave o cúrcuma en la mezcla no solo le da un color increíble, sino que aporta propiedades antiinflamatorias naturales.', ' Nota la diferencia de pesadez estomacal frente a la hamburguesa de carne vacuna tradicional.', true),
('hamburguesa-soja', ARRAY['hamburguesa de soja']::text[], 'Opción de origen vegetal basada en legumbres. Aporta proteínas vegetales y fibra, aunque su impacto glucémico depende en gran medida de los aditivos y almidones que tenga la marca.', 'Revisa el listado de ingredientes para evitar que el primer componente sea harina refinada en lugar de grano de soja texturizado o poroto. Tip extra: cocinala con un toque de salsa de soja baja en sodio y jengibre para realzar el umami natural.', ' Presta atención a la respuesta de tu abdomen; las legumbres procesadas pueden generar algo de hinchazón en personas sensibles.', true),
('hamburguesa-semillas', ARRAY['hamburguesa de semillas', 'hamburguesa de quinoa', 'hamburguesa de chia']::text[], 'Aporte interesante de grasas saludables (omega-3 de la chía) y aminoácidos completos de la quinoa. Una alternativa rica en fibra y micronutrientes.', 'Al tener alta concentración de semillas enteras, es fundamental una excelente masticación para que el cuerpo pueda aprovechar sus nutrientes reales y no pasen de largo. Tip extra: acompañala con un medio limón exprimido por encima para mejorar la absorción de los minerales de las semillas.', ' Evalúa el tránsito intestinal y la saciedad a largo plazo gracias al alto contenido de fibra soluble e insoluble.', true),
('medallon-merluza', ARRAY['medallon de merluza', 'patitas de pescado']::text[], 'Versión comercial procesada del pescado. Aporta proteína pero viene acompañada de una capa importante de rebozado industrial y harinas refinadas.', 'Si vas a consumirlos, prioriza hacerlos al horno a temperatura fuerte en lugar de freírlos para no duplicar la carga de aceites oxidados. Tip extra: rocialos con jugo de limón antes de comer para cortar la pesadez de la costra frita o al horno.', ' Compara la energía post-comida frente a un bife de pescado real; los medallones industriales suelen generar más letargo por el combo harina + grasa de cocción.', true),
('medallon-brocoli', ARRAY['medallon de brocoli']::text[], 'Apariencia saludable por el brócoli, pero comercialmente suele estar sostenido por una base alta de féculas, harinas y aditivos para mantener la forma.', 'No lo consideres un reemplazo equivalente a comer un plato de brócoli real; miralo como un opcional de hidratos con un toque vegetal. Tip extra: sumale una salsa a base de oliva y ajo al plato para levantar el perfil nutricional.', ' Chequea si te genera la misma saciedad que una verdura entera o si al rato sentís el bache de hambre por el almidón refinado del rebozado.', true),
('medallon-espinaca', ARRAY['medallon de espinaca']::text[], 'Similar al de brócoli: la espinaca aporta color y micronutrientes, pero el rebozado industrial domina la carga de carbohidratos del plato.', 'Cocinalos bien crocantes al horno para mejorar la experiencia sensorial y evitar la textura gomosa típica del producto descongelado. Tip extra: un toque de nuez moscada realza el sabor de la espinaca y disimula el gusto industrial.', ' Presta atención a cómo responde tu glucemia y tus ganas de picotear dulce a la hora de haber comido.', true),
('medallon-jamon-queso', ARRAY['medallon de jamon y queso', 'medallon jamon y queso']::text[], 'Un formato de comida rápida procesada. Alta densidad de grasas saturadas industriales, harinas refinadas y sodio, con un aporte proteico secundario.', 'Trata de que sea un consumo ocasional dentro de tu semana y combinalo siempre con una buena porción de ensalada cruda para aportar fibra viva que amortigüe el impacto. Tip extra: un toque de pimienta negra ayuda a estimular la digestión de este tipo de procesados pesados.', ' Registra el nivel de pesadez estomacal y sed posterior debido al alto contenido de sodio y grasas cocidas.', true),
('lampreado-marinera', ARRAY['lampreado', 'marinera', 'carne a la marinera']::text[], 'Carne o pollo sumergidos en una mezcla espesa de huevo y harina antes de freír. Capa de carbohidratos densa que absorbe una cantidad importante de aceite.', 'Dejá escurrir el exceso de fritura sobre papel absorbente y consumilo caliente para evitar que la costra se ponga reseca o demasiado pesada. Tip extra: el clásico baño de jugo de limón por encima cumple una doble función: corta la grasa en boca y aligera la digestión.', ' Evalúa la velocidad de digestión; este tipo de preparaciones pesadas suelen requerir un tiempo de reposo estomacal más largo.', true),
('sandwich-milanesa', ARRAY['sandwich de milanesa', 'sanguche de milanesa']::text[], 'El rey indiscutido de la calle y los bodegones. Un monumento al placer gastronómico que combina proteína frita/horneada con una gran cantidad de carbohidratos refinados del pan.', 'Si querés hackear el impacto glucémico sin arruinar la experiencia, abrilo al medio y sacale la miga superior del pan, o sumale una base generosa de lechuga y tomate adentro para meter fibra antes de que actúe el pan y el rebozado. Tip extra: un buen chimichurri casero con ajo y vinagre ayuda a procesar las grasas pesadas del sándwich.', ' Nota el pico de energía inmediato seguido de una posible modorra o bajón a las pocas horas por el combo masivo de carbohidratos y grasas.', true),
('hamburguesa-comercial', ARRAY['hamburguesa comercial', 'hamburguesa de fast food', 'sandwich de hamburguesa']::text[], 'Alimento ultraprocesado por excelencia. Pan blanco de miga ultra suave, medallón industrial y salsas comerciales con alta carga de azúcares ocultos y sodio.', 'Pedila sin salsas industriales dulces (como aderezos azucarados) y prioriza acompañarla con agua en lugar de gaseosas azucaradas para no duplicar el daño metabólico. Tip extra: comé primero los vegetales si el sándwich trae ensalada adentro antes de morder el pan.', ' Detecta la sed intensa post-comida y la rapidez con la que vuelve el apetito debido a la rápida absorción de los azúcares del pan refinado.', true),
('lomito', ARRAY['lomito', 'sandwich de lomo', 'sanguche de lomo']::text[], 'El hermano mayor de los sándwiches. Aporta una excelente cantidad de proteína magra de carne vacuna, pero viene envuelto en un pan grande y acompañado de fiambres o aderezos.', 'Si podés elegir el pan, optá por una opción de masa más compacta o retirale parte de la miga. Prioriza aderezos naturales (como provenzal o criolla) antes que mayonesas industriales pesadas. Tip extra: una infusión digestiva (como té de menta o carqueja) post-sándwich ayuda a evitar la sensación de abdomen inflado.', ' Compara la saciedad brutal que te deja este sándwich frente a una hamburguesa comercial; la carne de lomo real marca una diferencia gigante en el tiempo sin hambre.', true),
('asado-tira', ARRAY['asado', 'asado de tira', 'tira de asado']::text[], '¡Excelente elección! El ritual sagrado de nuestra carne. Aporta proteínas de primera y grasas naturales que, lejos de ser el enemigo, son fundamentales para la saciedad y la salud hormonal si no se abusa de los azúcares con los que se acompaña.', 'Disfrutá la carne priorizando los sectores más magros o equilibrando la grasa tostada. No te recargues de pan blanco mientras sale el asado. Tip extra: acompañalo con una salsa criolla abundante (tomate, cebolla y morrón crudos con vinagre y aceite); la acidez del vinagre y los vegetales crudos son el antídoto digestivo perfecto para las carnes grasas a la parrilla.', ' Registra la saciedad extrema y placentera que te otorga; es un alimento que estabiliza el apetito por horas.', true),
('vacio', ARRAY['vacio', 'vacio a la parrilla']::text[], '¡Excelente elección! Un corte magro por excelencia dentro de los cortes parrilleros. Mucha fibra muscular, proteína noble y un contenido graso externo muy fácil de manejar.', 'Cocinalo a fuego lento para que quede tierno sin quemar la superficie. Es un aliado perfecto para planes de rendimiento y recomposición corporal. Tip extra: un buen chimichurri casero con ajo fresco estimula las secreciones gástricas y potencia la asimilación de los aminoácidos del corte.', ' Nota la energía limpia y sostenida que te deja este corte; es ideal para días de entrenamiento intenso o actividad física exigente.', true),
('matambre', ARRAY['matambre', 'matambre a la pizza', 'matambre tierno']::text[], '¡Excelente elección! Corte tradicional con un perfil proteico muy alto. Ya sea a la pizza o tierno a la leche, aporta una textura y satisfacción incomparables.', 'Si lo hacés a la pizza, moderá la cantidad de queso o elegí una muzarella de buena calidad para evitar sumar un exceso de grasa pesada. Tip extra: un toque de provenzal o ají molido realza el sabor profundo de este corte y ayuda a una digestión más ágil.', ' Evalúa cómo responde tu estómago; al ser un corte fibroso, requiere una buena masticación que de por sí ya activa el proceso de saciedad cerebral.', true),
('chorizo', ARRAY['chorizo', 'chorizo criollo', 'chorizo bombom']::text[], 'Embutido tradicional de alta densidad calórica y grasa. Aporta sabor intenso y energía rápida, pero su procesamiento industrial puede variar drásticamente según la calidad del chacinado.', 'Pinchalo antes de cocinarlo a la parrilla para que libere parte de su grasa excedente al fuego, o elegí versiones artesanales de cerdo puro y baja carga de aditivos. Tip extra: consumilo siempre acompañado de una picada de vegetales frescos o ensalada verde para equilibrar el impacto lipídico en el plato.', ' Nota la pesadez o el nivel de energía sostenida; al ser un alimento muy graso, su digestión es lenta y demanda mayor trabajo metabólico.', true),
('morcilla', ARRAY['morcilla', 'morcilla vasca', 'morcilla criolla']::text[], '¡Joyita nutricional a su manera! Aporta una cantidad masiva de hierro, zinc y minerales gracias a su base de sangre, combinada con grasas y especias.', 'No la abuses si tenés digestiones lentas, pero integrala como un excelente bocado ocasional de alta densidad de micronutrientes. Tip extra: un toque de limón o vinagre al cortarla en el plato contrarresta la pesadez grasa y realza el sabor metálico del hierro.', ' Presta atención a la energía y saciedad que te otorga; es un alimento denso que corta el apetito de manera fulminante.', true),
('salchichas', ARRAY['salchichas', 'panchos', 'salchichas de viena']::text[], 'Alimento ultraprocesado por antonomasia. Textura homogénea lograda mediante molienda fina de subproductos cárnicos, almidones, aditivos y altos niveles de sodio.', 'Si están en tu menú por practicidad, saltealás o hervilas y acompañalas obligatoriamente con una fuente gigante de fibra cruda para amortiguar el impacto metabólico de los aditivos. Tip extra: una buena cucharada de mostaza natural ayuda a enmascarar el exceso de sodio y estimula la digestión.', ' Detecta la sed posterior y la rapidez con la que vuelve el hambre; al ser un ultraprocesado de rápida absorción, no genera saciedad real a largo plazo.', true)
